    case 29: /* CONSTRAINT_CATALOG */
    case 30: /* CONSTRAINT_NAME */
    case 31: /* CONSTRAINT_SCHEMA */
    case 32: /* CONTAINS */
    case 33: /* CONTEXT */
    case 34: /* CONVERT */
    case 35: /* CPU */
    case 36: /* CURRENT */
    case 37: /* CURSOR_NAME */
    case 38: /* CURRENT_USER */
    case 39: /* DATAFILE */
    case 40: /* DECIMAL */
    case 41: /* DEFINITION */
    case 42: /* DELAY_KEY_WRITE */
    case 43: /* DESCRIPTION */
    case 44: /* DETERMINISTIC */
    case 45: /* DIRECTORY */
    case 46: /* DISABLE */
    case 47: /* DISCARD */
    case 48: /* DUPLICATE */
    case 49: /* EACH */
    case 50: /* ENABLE */
